codeExample.bad:
// On session expiry, the in-progress form data is simply discarded,
// and the user starts over completely after logging back in
function onSessionExpired() {
  redirectToLogin();
  // Form state is lost; nothing is saved
}

codeExample.good:
// On session expiry, form data is saved locally before redirecting,
// and restored automatically after re-authentication succeeds
function onSessionExpired() {
  saveDraftLocally(getCurrentFormState());
  redirectToLogin({ returnTo: currentUrl });
}
function onLoginSuccess() {
  const draft = loadDraftLocally();
  if (draft) restoreFormState(draft);
}
